=== event/EventBus.java
     1	package br.com.marealta.pousada.event;
     2	
     3	import java.util.List;
     4	import java.util.Map;
     5	import java.util.concurrent.ConcurrentHashMap;
     6	import java.util.concurrent.CopyOnWriteArrayList;
     7	import java.util.function.Consumer;
     8	import org.slf4j.Logger;
     9	import org.slf4j.LoggerFactory;
    10	
    11	/**
    12	 * Minimal synchronous publish/subscribe. New interested parties (restaurant, airport transfer, ...)
    13	 * just subscribe; the reservation code does not change.
    14	 */
    15	public class EventBus {
    16	    private static final Logger log = LoggerFactory.getLogger(EventBus.class);
    17	
    18	    private final Map<Class<?>, List<Consumer<Object>>> handlers = new ConcurrentHashMap<>();
    19	
    20	    @SuppressWarnings("unchecked")
    21	    public <E> void subscribe(Class<E> type, Consumer<? super E> handler) {
    22	        handlers.computeIfAbsent(type, t -> new CopyOnWriteArrayList<>()).add((Consumer<Object>) handler);
    23	    }
    24	
    25	    public void publish(Object event) {
    26	        // dispatch to handlers registered for the concrete class or any of its supertypes
    27	        handlers.forEach((type, list) -> {
    28	            if (type.isInstance(event)) {
    29	                for (Consumer<Object> handler : list) {
    30	                    try {
    31	                        handler.accept(event);
    32	                    } catch (RuntimeException e) {
    33	                        // one failing subscriber must not undo the operation or block the others
    34	                        log.error("Subscriber failed for {}", event, e);
    35	                    }
    36	                }
    37	            }
    38	        });
    39	    }
    40	}
