     1	package br.com.marealta.pousada.notification;
     2	
     3	import br.com.marealta.pousada.domain.Money;
     4	import br.com.marealta.pousada.domain.Receipt;
     5	import br.com.marealta.pousada.domain.Reservation;
     6	import br.com.marealta.pousada.event.EventBus;
     7	import br.com.marealta.pousada.event.ReservationEvent;
     8	
     9	/** Wires every notification audience to the reservation events. */
    10	public class Notifications {
    11	    public static final String GOVERNANCE = "governanca@pousadamarealta.com.br";
    12	    public static final String FINANCE = "financeiro@pousadamarealta.com.br";
    13	
    14	    private final MessageLog log;
    15	
    16	    private Notifications(MessageLog log) {
    17	        this.log = log;
    18	    }
    19	
    20	    public static void register(EventBus bus, MessageLog log) {
    21	        Notifications n = new Notifications(log);
    22	        bus.subscribe(ReservationEvent.Confirmed.class, n::guestConfirmed);
    23	        bus.subscribe(ReservationEvent.Confirmed.class, n::governanceConfirmed);
    24	        bus.subscribe(ReservationEvent.Confirmed.class, n::financeConfirmed);
    25	        bus.subscribe(ReservationEvent.Cancelled.class, n::governanceCancelled);
    26	        bus.subscribe(ReservationEvent.Cancelled.class, n::financeCancelled);
    27	    }
    28	
    29	    private void email(String to, String subject, String body) {
    30	        log.send(Channel.EMAIL, to, subject, body);
    31	    }
    32	
    33	    private void guestConfirmed(ReservationEvent.Confirmed e) {
    34	        Reservation r = e.reservation();
    35	        String body = "Olá, " + r.guestName() + "!\n\n"
    36	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    37	                + Receipt.of(r).text() + "\n\n"
    38	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    39	                + "Até breve!";
    40	        email(r.guestEmail(), "Reserva confirmada - Pousada Maré Alta", body);
    41	    }
    42	
    43	    private void governanceConfirmed(ReservationEvent.Confirmed e) {
    44	        Reservation r = e.reservation();
    45	        String body = "Reserva nº " + r.id() + " confirmada para o quarto " + r.room().number()
    46	                + " (" + r.room().type() + ").\n"
    47	                + "Entrada: " + Receipt.formatDate(r.checkIn()) + "\n"
    48	                + "Saída: " + Receipt.formatDate(r.checkOut()) + "\n"
    49	                + "Hóspedes: " + r.guests();
    50	        email(GOVERNANCE, "Reserva confirmada - quarto " + r.room().number(), body);
    51	    }
    52	
    53	    private void financeConfirmed(ReservationEvent.Confirmed e) {
    54	        Reservation r = e.reservation();
    55	        String body = "Pagamento recebido da reserva nº " + r.id() + ": " + Money.format(r.amountPaid()) + ".";
    56	        email(FINANCE, "Pagamento recebido - reserva " + r.id(), body);
    57	    }
    58	
    59	    private void governanceCancelled(ReservationEvent.Cancelled e) {
    60	        if (!e.wasConfirmed()) {
    61	            return;
    62	        }
    63	        Reservation r = e.reservation();
    64	        String body = "A reserva nº " + r.id() + " do quarto " + r.room().number() + " foi cancelada.\n"
    65	                + "Datas liberadas: de " + Receipt.formatDate(r.checkIn())
    66	                + " (entrada) a " + Receipt.formatDate(r.checkOut()) + " (saída).";
    67	        email(GOVERNANCE, "Reserva cancelada - quarto " + r.room().number(), body);
    68	    }
    69	
    70	    private void financeCancelled(ReservationEvent.Cancelled e) {
    71	        Reservation r = e.reservation();
    72	        if (!e.wasConfirmed() || r.refund() == null || r.refund().signum() <= 0) {
    73	            return;
    74	        }
    75	        String body = "Reembolso da reserva nº " + r.id() + ": valor a devolver " + Money.format(r.refund()) + ".";
    76	        email(FINANCE, "Reembolso - reserva " + r.id(), body);
    77	    }
    78	}
