     1	package br.com.marealta.pousada.service;
     2	
     3	import br.com.marealta.pousada.domain.Money;
     4	import br.com.marealta.pousada.domain.Pricing;
     5	import br.com.marealta.pousada.domain.RatePlan;
     6	import br.com.marealta.pousada.domain.Receipt;
     7	import br.com.marealta.pousada.domain.Reservation;
     8	import br.com.marealta.pousada.domain.ReservationStatus;
     9	import br.com.marealta.pousada.domain.Room;
    10	import br.com.marealta.pousada.domain.RoomType;
    11	import br.com.marealta.pousada.event.EventBus;
    12	import br.com.marealta.pousada.event.ReservationEvent;
    13	import java.math.BigDecimal;
    14	import java.time.LocalDate;
    15	import java.util.ArrayList;
    16	import java.util.LinkedHashMap;
    17	import java.util.List;
    18	import java.util.Map;
    19	
    20	public class ReservationService {
    21	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    22	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    23	    }
    24	
    25	    private final EventBus events;
    26	    private final List<Room> rooms = List.of(
    27	            new Room(101, RoomType.STANDARD),
    28	            new Room(102, RoomType.STANDARD),
    29	            new Room(201, RoomType.DELUXE),
    30	            new Room(202, RoomType.DELUXE),
    31	            new Room(301, RoomType.SUITE));
    32	    private final Map<Long, Reservation> reservations = new LinkedHashMap<>();
    33	    private long nextId = 1;
    34	
    35	    public ReservationService(EventBus events) {
    36	        this.events = events;
    37	    }
    38	
    39	    public List<Room> rooms() {
    40	        return rooms;
    41	    }
    42	
    43	    public synchronized Reservation create(NewReservation req) {
    44	        if (!req.checkOut().isAfter(req.checkIn())) {
    45	            throw DomainException.invalid("A saída deve ser depois da entrada");
    46	        }
    47	        if (req.guests() < 1) {
    48	            throw DomainException.invalid("É preciso pelo menos um hóspede");
    49	        }
    50	        Room room = rooms.stream().filter(r -> r.number() == req.roomNumber()).findFirst()
    51	                .orElseThrow(() -> new DomainException(404, "ROOM_NOT_FOUND", "Quarto não encontrado"));
    52	        if (req.guests() > room.capacity()) {
    53	            throw new DomainException(422, "CAPACITY_EXCEEDED",
    54	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    55	        }
    56	        boolean taken = reservations.values().stream()
    57	                .anyMatch(r -> r.room().equals(room) && r.status() != ReservationStatus.CANCELLED
    58	                        && r.overlaps(req.checkIn(), req.checkOut()));
    59	        if (taken) {
    60	            throw new DomainException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    61	        }
    62	        Pricing.Quote quote = Pricing.quote(room, req.checkIn(), req.checkOut(), req.ratePlan());
    63	        Reservation reservation = new Reservation(nextId++, room, req.guestName(), req.guestEmail(), req.guestCpf(),
    64	                req.checkIn(), req.checkOut(), req.guests(), req.ratePlan(), quote.nights(), quote.subtotal(),
    65	                quote.discount(), quote.total(), ReservationStatus.PENDING, Money.ZERO, null);
    66	        reservations.put(reservation.id(), reservation);
    67	        return reservation;
    68	    }
    69	
    70	    public synchronized Reservation get(long id) {
    71	        Reservation r = reservations.get(id);
    72	        if (r == null) {
    73	            throw notFound();
    74	        }
    75	        return r;
    76	    }
    77	
    78	    public synchronized List<Reservation> all() {
    79	        return new ArrayList<>(reservations.values());
    80	    }
    81	
    82	    public synchronized Reservation confirm(long id) {
    83	        Reservation current = requireStatus(id, "confirmar", ReservationStatus.PENDING);
    84	        Reservation confirmed = current.confirmed();
    85	        reservations.put(id, confirmed);
    86	        events.publish(new ReservationEvent.Confirmed(confirmed));
    87	        return confirmed;
    88	    }
    89	
    90	    public synchronized Reservation checkIn(long id) {
    91	        Reservation current = requireStatus(id, "fazer check-in de", ReservationStatus.CONFIRMED);
    92	        Reservation updated = current.withStatus(ReservationStatus.CHECKED_IN);
    93	        reservations.put(id, updated);
    94	        return updated;
    95	    }
    96	
    97	    public synchronized Receipt checkOut(long id) {
    98	        Reservation current = requireStatus(id, "fazer check-out de", ReservationStatus.CHECKED_IN);
    99	        Reservation updated = current.withStatus(ReservationStatus.CHECKED_OUT);
   100	        reservations.put(id, updated);
   101	        return Receipt.of(updated);
   102	    }
   103	
   104	    public synchronized Reservation cancel(long id) {
   105	        Reservation current = requireStatus(id, "cancelar", ReservationStatus.PENDING, ReservationStatus.CONFIRMED);
   106	        boolean wasConfirmed = current.status() == ReservationStatus.CONFIRMED;
   107	        BigDecimal refund = wasConfirmed && current.ratePlan().refundable() ? current.amountPaid() : Money.ZERO;
   108	        Reservation cancelled = current.cancelled(refund);
   109	        reservations.put(id, cancelled);
   110	        events.publish(new ReservationEvent.Cancelled(cancelled, wasConfirmed));
   111	        return cancelled;
   112	    }
   113	
   114	    public synchronized Receipt document(long id) {
   115	        Reservation r = get(id);
   116	        if (!r.status().paid()) {
   117	            throw new DomainException(409, "OPERATION_NOT_ALLOWED",
   118	                    "A segunda via só existe para reserva paga");
   119	        }
   120	        return Receipt.of(r);
   121	    }
   122	
   123	    private Reservation requireStatus(long id, String action, ReservationStatus... allowed) {
   124	        Reservation r = get(id);
   125	        for (ReservationStatus s : allowed) {
   126	            if (r.status() == s) {
   127	                return r;
   128	            }
   129	        }
   130	        throw new DomainException(409, "OPERATION_NOT_ALLOWED",
   131	                "Não é possível " + action + " uma reserva com situação " + r.status());
   132	    }
   133	
   134	    private static DomainException notFound() {
   135	        return new DomainException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
   136	    }
   137	}

