 26	public class Api {
 27	    private static final ObjectMapper MAPPER = new ObjectMapper()
 28	            .registerModule(new JavaTimeModule())
 29	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 30	            .enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
 31	
 32	    private final ReservationService reservations;
 33	    private final ReportService reports;
 34	    private final MessageLog messages;
 35	
 36	    public Api() {
 37	        EventBus bus = new EventBus();
 38	        this.messages = new MessageLog();
 39	        this.reservations = new ReservationService(bus);
 40	        this.reports = new ReportService(reservations);
 41	        Notifications.register(bus, messages);
 42	    }
 43	
 44	    public Javalin create() {
 45	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
 46	
 47	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.status(), e.code(), e.getMessage()));
 48	        app.exception(Exception.class, (e, ctx) -> error(ctx, 500, "INTERNAL_ERROR", "Erro interno"));
 49	
 50	        app.get("/rooms", ctx -> json(ctx, 200, reservations.rooms().stream().map(Api::roomView).toList()));
 51	        app.post("/reservations", ctx -> json(ctx, 201, view(reservations.create(parseNew(ctx)))));
 52	        app.get("/reservations/{id}", ctx -> json(ctx, 200, view(reservations.get(id(ctx)))));
 53	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, view(reservations.confirm(id(ctx)))));
 54	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, view(reservations.cancel(id(ctx)))));
 55	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, view(reservations.checkIn(id(ctx)))));
 56	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, reservations.checkOut(id(ctx))));
 57	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, reservations.document(id(ctx))));
 58	        app.get("/messages", ctx -> json(ctx, 200, messages.all()));
 59	
 60	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(parseDate(ctx.queryParam("date"), "date"))));
 61	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(parseMonth(ctx.queryParam("month")))));
 62	        return app;
 63	    }
