 92	        m.put("amountPaid", r.amountPaid());
 93	        m.put("refund", r.refund());
 94	        return m;
 95	    }
 96	
 97	    // ---- request parsing ----
 98	
 99	    private static NewReservation parseNew(Context ctx) {
100	        JsonNode body;
101	        try {
102	            body = MAPPER.readTree(ctx.body());
103	        } catch (JsonProcessingException e) {
104	            throw DomainException.invalid("Corpo da requisição não é um JSON válido");
105	        }
106	        if (body == null || !body.isObject()) {
107	            throw DomainException.invalid("Corpo da requisição deve ser um objeto JSON");
108	        }
109	        int roomNumber = integer(body, "roomNumber");
110	        String name = text(body, "guestName");
111	        String email = text(body, "guestEmail");
112	        String cpf = text(body, "guestCpf");
113	        LocalDate checkIn = parseDate(text(body, "checkIn"), "checkIn");
114	        LocalDate checkOut = parseDate(text(body, "checkOut"), "checkOut");
115	        int guests = integer(body, "guests");
116	        RatePlan plan;
117	        try {
118	            plan = RatePlan.valueOf(text(body, "ratePlan"));
119	        } catch (IllegalArgumentException e) {
120	            throw DomainException.invalid("ratePlan inválido");
121	        }
122	        return new NewReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
123	    }
124	
125	    private static String text(JsonNode body, String field) {
126	        JsonNode n = body.get(field);
127	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
128	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
129	        }
130	        return n.asText();
131	    }
132	
133	    private static int integer(JsonNode body, String field) {
134	        JsonNode n = body.get(field);
135	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
136	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
137	        }
138	        return n.intValue();
139	    }
140	
141	    private static LocalDate parseDate(String value, String field) {
142	        if (value == null) {
143	            throw DomainException.invalid("Parâmetro obrigatório: " + field);
144	        }
145	        try {
146	            return LocalDate.parse(value);
147	        } catch (DateTimeParseException e) {
148	            throw DomainException.invalid("Data inválida em " + field + " (use aaaa-mm-dd)");
149	        }
150	    }
151	
152	    private static YearMonth parseMonth(String value) {
153	        if (value == null) {
154	            throw DomainException.invalid("Parâmetro obrigatório: month");
155	        }
156	        try {
157	            return YearMonth.parse(value);
158	        } catch (DateTimeParseException e) {
159	            throw DomainException.invalid("Mês inválido (use aaaa-mm)");
160	        }
161	    }
162	
163	    private static long id(Context ctx) {
164	        try {
165	            return Long.parseLong(ctx.pathParam("id"));
166	        } catch (NumberFormatException e) {
167	            throw new DomainException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
168	        }
169	    }
170	
171	    // ---- responses ----
172	
173	    private static void json(Context ctx, int status, Object body) {
174	        try {
175	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
176	        } catch (JsonProcessingException e) {
177	            throw new IllegalStateException(e);
178	        }
179	    }
180	
181	    private static void csv(Context ctx, String body) {
182	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
183	    }
184	
185	    private static void error(Context ctx, int status, String code, String message) {
186	        Map<String, Object> m = new LinkedHashMap<>();
187	        m.put("error", code);
188	        m.put("message", message);
189	        json(ctx, status, m);
190	    }
191	}
