  9	public final class Money {
 10	    public static final BigDecimal ZERO = round(BigDecimal.ZERO);
 11	
 12	    private Money() {
 13	    }
 14	
 15	    /** Rounds to cents, half-to-even. */
 16	    public static BigDecimal round(BigDecimal value) {
 17	        return value.setScale(2, RoundingMode.HALF_EVEN);
 18	    }
 19	
 20	    /** Formats as "R$ 1.234,56". */
 21	    public static String format(BigDecimal value) {
