 99	    private static NewReservation parseNew(Context ctx) {
100	        JsonNode body;
101	        try {
102	            body = MAPPER.readTree(ctx.body());
103	        } catch (JsonProcessingException e) {
104	            throw DomainException.invalid("Corpo da requisição não é um JSON válido");
105	        }
106	        if (body == null || !body.isObject()) {
107	            throw DomainException.invalid("Corpo da requisição deve ser um objeto JSON");
108	        }
109	        int roomNumber = integer(body, "roomNumber");
110	        String name = text(body, "guestName");
111	        String email = text(body, "guestEmail");
112	        String cpf = text(body, "guestCpf");
113	        LocalDate checkIn = parseDate(text(body, "checkIn"), "checkIn");
114	        LocalDate checkOut = parseDate(text(body, "checkOut"), "checkOut");
115	        int guests = integer(body, "guests");
116	        RatePlan plan;
117	        try {
118	            plan = RatePlan.valueOf(text(body, "ratePlan"));
119	        } catch (IllegalArgumentException e) {
120	            throw DomainException.invalid("ratePlan inválido");
121	        }
122	        return new NewReservation(roomNumber, name, email, cpf, checkIn, checkOut, guests, plan);
