133	    private static int integer(JsonNode body, String field) {
134	        JsonNode n = body.get(field);
135	        if (n == null || !n.isIntegralNumber() || !n.canConvertToInt()) {
136	            throw DomainException.invalid("Campo obrigatório ausente ou inválido: " + field);
137	        }
138	        return n.intValue();
139	    }
