141	    private static LocalDate parseDate(String value, String field) {
142	        if (value == null) {
143	            throw DomainException.invalid("Parâmetro obrigatório: " + field);
144	        }
145	        try {
146	            return LocalDate.parse(value);
147	        } catch (DateTimeParseException e) {
148	            throw DomainException.invalid("Data inválida em " + field + " (use aaaa-mm-dd)");
149	        }
150	    }
