152	    private static YearMonth parseMonth(String value) {
153	        if (value == null) {
154	            throw DomainException.invalid("Parâmetro obrigatório: month");
155	        }
156	        try {
157	            return YearMonth.parse(value);
158	        } catch (DateTimeParseException e) {
159	            throw DomainException.invalid("Mês inválido (use aaaa-mm)");
160	        }
