 34	public final class Pricing {
 35	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
 36	
 37	    private Pricing() {
 38	    }
 39	
 40	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
 41	    }
 42	
 43	    public static boolean highSeason(LocalDate night) {
 44	        Month month = night.getMonth();
 45	        return month == Month.JULY || month == Month.JANUARY || month == Month.FEBRUARY
 46	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
 47	    }
 48	
 49	    public static BigDecimal nightPrice(Room room, LocalDate night) {
 50	        BigDecimal rate = room.nightlyRate();
 51	        return Money.round(highSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
 52	    }
 53	
 54	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
 55	        BigDecimal subtotal = Money.ZERO;
 56	        int nights = 0;
 57	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 58	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
 59	            nights++;
 60	        }
 61	        BigDecimal discount = Money.round(subtotal.multiply(plan.discountRate()));
 62	        BigDecimal total = Money.round(subtotal.subtract(discount));
 63	        return new Quote(nights, subtotal, discount, total);
 64	    }
 65	}
